CREATE TABLE IF NOT EXISTS providers(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) UNIQUE NOT NULL,website VARCHAR(255));
CREATE TABLE IF NOT EXISTS scholarships(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(220) NOT NULL,slug VARCHAR(240) UNIQUE NOT NULL,provider_id INT NOT NULL,description TEXT,eligibility TEXT,benefits TEXT,country_of_study VARCHAR(80),degree_level VARCHAR(40),field VARCHAR(120) DEFAULT 'All fields',funding_type VARCHAR(40) DEFAULT 'Fully funded',deadline DATE NULL,application_url VARCHAR(400),featured TINYINT(1) DEFAULT 0,status ENUM('draft','published','expired') DEFAULT 'published',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(status,deadline),INDEX(country_of_study),INDEX(degree_level),FOREIGN KEY(provider_id) REFERENCES providers(id));
CREATE TABLE IF NOT EXISTS subscribers(id INT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) UNIQUE NOT NULL,degree_level VARCHAR(40),status ENUM('active','unsubscribed') DEFAULT 'active',unsubscribe_token CHAR(32) NOT NULL,subscribed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admins(id INT PRIMARY KEY,username VARCHAR(60) NOT NULL,password_hash VARCHAR(255) NOT NULL)
